func TestChatRequestJSONContract(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN is not set")
	}

	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	cipher, err := secrets.New(bytes.Repeat([]byte{9}, 32))
	if err != nil {
		t.Fatal(err)
	}
	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
	service := httptest.NewServer(handler)
	defer service.Close()
	session := signIn(t, handler)
	client := service.Client()
	client.Timeout = 10 * time.Second

	// Keep raw bytes intact: session.do marshals its argument as a single JSON value.
	post := func(t *testing.T, path string, body []byte) (int, []byte) {
		t.Helper()
		request, err := http.NewRequest(http.MethodPost, service.URL+path, bytes.NewReader(body))
		if err != nil {
			t.Fatal(err)
		}
		request.Header.Set("Content-Type", "application/json")
		request.Header.Set("X-CSRF-Token", session.csrf)
		for _, cookie := range session.cookies {
			request.AddCookie(cookie)
		}
		response, err := client.Do(request)
		if err != nil {
			t.Fatalf("POST %s: %v", path, err)
		}
		defer response.Body.Close()
		relayed, err := io.ReadAll(response.Body)
		if err != nil {
			t.Fatalf("read response: %v", err)
		}
		return response.StatusCode, relayed
	}
	marshal := func(value any) []byte {
		t.Helper()
		raw, err := json.Marshal(value)
		if err != nil {
			t.Fatal(err)
		}
		return raw
	}

	const answer = `{"id":"chatcmpl-json-contract","choices":[{"message":{"role":"assistant","content":"안녕하세요 {} null xyz"}}]}`
	var mu sync.Mutex
	var calls int
	var lastPayload map[string]any
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var payload map[string]any
		err := json.NewDecoder(r.Body).Decode(&payload)
		mu.Lock()
		calls++
		lastPayload = payload
		mu.Unlock()
		if err != nil {
			t.Errorf("decode upstream request: %v", err)
			http.Error(w, "invalid upstream request", http.StatusBadRequest)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = io.WriteString(w, answer)
	}))
	defer upstream.Close()
	callCount := func() int {
		mu.Lock()
		defer mu.Unlock()
		return calls
	}

	assertInvalidJSON := func(t *testing.T, body []byte) {
		t.Helper()
		before := callCount()
		status, relayed := post(t, "/v1/chat/completions", body)
		if got := callCount() - before; got != 0 {
			t.Errorf("upstream calls=%d want=0", got)
		}
		if status != http.StatusBadRequest {
			t.Errorf("status=%d want=400 body=%s", status, relayed)
		}
		var envelope struct {
			Error struct {
				Code string `json:"code"`
			} `json:"error"`
		}
		if err := json.Unmarshal(relayed, &envelope); err != nil {
			t.Fatalf("decode rejection: %v", err)
		}
		if envelope.Error.Code != "invalid_json" {
			t.Errorf("error code=%q want=invalid_json", envelope.Error.Code)
		}
	}
	rejectNonObjects := func(t *testing.T) {
		t.Helper()
		for _, testCase := range []struct {
			name string
			body string
		}{
			{name: "null", body: "null"},
			{name: "null_with_json_whitespace", body: " \t\r\nnull \t\r\n"},
			{name: "array", body: "[]"},
			{name: "string", body: `"hello"`},
			{name: "number", body: "42"},
			{name: "boolean_true", body: "true"},
			{name: "boolean_false", body: "false"},
		} {
			t.Run(testCase.name, func(t *testing.T) {
				assertInvalidJSON(t, []byte(testCase.body))
			})
		}
	}
	t.Run("without_default_provider", rejectNonObjects)

	status, created := post(t, "/api/v1/ai/providers", marshal(map[string]any{
		"name": "JSON 요청 공급자", "type": "openai-compatible", "baseUrl": upstream.URL,
		"defaultModel": "test-model", "contextWindow": 131072, "maxOutputTokens": 8192,
	}))
	if status != http.StatusCreated {
		t.Fatalf("provider status=%d body=%s", status, created)
	}
	var providerEnvelope struct {
		Data struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	if err := json.Unmarshal(created, &providerEnvelope); err != nil {
		t.Fatal(err)
	}
	if providerEnvelope.Data.ID == "" {
		t.Fatal("provider creation returned no ID")
	}

	settingsResponse := session.do(t, handler, http.MethodPatch, "/api/v1/settings", map[string]any{
		"values": map[string]any{"ai.default_provider_id": providerEnvelope.Data.ID},
	})
	if settingsResponse.Code != http.StatusOK {
		t.Fatalf("settings status=%d body=%s", settingsResponse.Code, settingsResponse.Body.String())
	}
	t.Run("with_default_provider", rejectNonObjects)

	wantMessages := []any{map[string]any{"role": "user", "content": "문자열 안의 {} null xyz는 그대로 보존"}}
	chatBody := func(providerID string) []byte {
		return marshal(map[string]any{
			"provider_id": providerID, "model": "test-model", "stream": false,
			"messages": wantMessages, "seed": 42,
		})
	}
	body := chatBody(providerEnvelope.Data.ID)
	const bodyLimit = 4 << 20
	for _, testCase := range []struct {
		name string
		body string
	}{
		{name: "single_object", body: string(body)},
		{name: "trailing_json_whitespace", body: string(body) + " \t\r\n"},
		{name: "whitespace_at_4_mib_limit", body: string(body) + strings.Repeat(" ", bodyLimit-len(body))},
		{name: "default_provider_and_model", body: string(marshal(map[string]any{
			"messages": wantMessages, "seed": 42, "stream": false,
		}))},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			before := callCount()
			status, relayed := post(t, "/v1/chat/completions", []byte(testCase.body))
			if got := callCount() - before; got != 1 {
				t.Errorf("upstream calls=%d want=1", got)
			}
			if status != http.StatusOK {
				t.Fatalf("status=%d want=200 body=%s", status, relayed)
			}
			if string(relayed) != answer {
				t.Errorf("relayed body=%q want=%q", relayed, answer)
			}
			mu.Lock()
			payload := lastPayload
			mu.Unlock()
			if !reflect.DeepEqual(payload["messages"], wantMessages) {
				t.Errorf("upstream messages=%v want=%v", payload["messages"], wantMessages)
			}
			if payload["seed"] != float64(42) || payload["model"] != "test-model" || payload["stream"] != false {
				t.Errorf("upstream seed/model/stream changed: %v", payload)
			}
			if _, supplied := payload["provider_id"]; supplied {
				t.Error("provider_id reached upstream")
			}
		})
	}

	for _, testCase := range []struct {
		name string
		body string
	}{
		{name: "trailing_object", body: string(body) + " {}"},
		{name: "trailing_null", body: string(body) + " null"},
		{name: "trailing_garbage", body: string(body) + " xyz"},
		{name: "whitespace_over_4_mib_limit", body: string(body) + strings.Repeat(" ", bodyLimit-len(body)+1)},
		// A missing provider must not mask the JSON error with provider_unavailable.
		{name: "reject_before_provider_selection", body: string(chatBody("00000000-0000-0000-0000-000000000001")) + " {}"},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			assertInvalidJSON(t, []byte(testCase.body))
		})
	}
}
		return joined
	}
	joined, _ := url.JoinPath(base, "v1", endpoint)
	return joined
}

func (s *Server) applyProviderAuth(request *http.Request, item provider) error {
	if len(item.EncryptedAPIKey) == 0 {
		return nil
	}
	plaintext, err := s.cipher.Decrypt(item.EncryptedAPIKey, "provider:"+item.ID.String()+":api-key")
	if err != nil || strings.TrimSpace(string(plaintext)) == "" || strings.ContainsAny(string(plaintext), "\r\n\x00") {
		return errProviderCredentials
	}
	request.Header.Set("Authorization", "Bearer "+string(plaintext))
	return nil
}

func (s *Server) chatCompletions(w http.ResponseWriter, r *http.Request) {
	p := principalFrom(r.Context())
	if p.AuthMethod == "api_key" && !p.HasScope("ai:chat") {
		writeError(w, http.StatusForbidden, "scope_denied", "API 키에 ai:chat scope가 없습니다.")
		return
	}
	mediaType, _, contentTypeErr := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if contentTypeErr != nil || !strings.EqualFold(mediaType, "application/json") {
		writeError(w, http.StatusUnsupportedMediaType, "content_type_invalid", "채팅 요청은 application/json 형식이어야 합니다.")
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, 4<<20)
	var payload map[string]any
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(&payload); err != nil || payload == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "채팅 요청 본문이 올바르지 않습니다.")
		return
	}
	var trailing json.RawMessage
	if err := decoder.Decode(&trailing); err != io.EOF {
		writeError(w, http.StatusBadRequest, "invalid_json", "채팅 요청 본문이 올바르지 않습니다.")
		return
	}
	providerIDText, _ := payload["provider_id"].(string)
	delete(payload, "provider_id")
	if providerIDText == "" {
		providerIDText = s.stringSetting(r.Context(), "ai.default_provider_id", "")
	}
	providerID, err := uuid.Parse(providerIDText)
	if err != nil {
		writeError(w, http.StatusServiceUnavailable, "provider_not_configured", "기본 AI 공급자가 설정되지 않았습니다.")
		return
	}
	item, err := s.loadProvider(r.Context(), providerID)
	if err != nil || !item.Enabled {
		writeError(w, http.StatusServiceUnavailable, "provider_unavailable", "선택한 AI 공급자를 사용할 수 없습니다.")
		return
	}
	if _, ok := payload["model"]; !ok {
		payload["model"] = item.DefaultModel
	}
	model, modelOK := payload["model"].(string)
	model = strings.TrimSpace(model)
	if !modelOK || model == "" || utf8.RuneCountInString(model) > 240 {
		writeError(w, http.StatusBadRequest, "model_invalid", "사용할 모델 이름이 올바르지 않습니다.")
		return
	}
	allowedModels := uniqueStrings(append([]string{item.DefaultModel}, item.AvailableModels...))
	if !containsString(allowedModels, model) {
		writeError(w, http.StatusBadRequest, "model_not_allowed", "선택한 모델은 이 공급자에 허용되지 않았습니다.")
		return
	}
	payload["model"] = model
	stream, hasStream := payload["stream"].(bool)
	if _, supplied := payload["stream"]; supplied && !hasStream {
		writeError(w, http.StatusBadRequest, "stream_invalid", "stream 값은 true 또는 false여야 합니다.")
		return
	}
	if !hasStream {
		stream = item.StreamDefault && s.boolSetting(r.Context(), "ai.stream_default", true)
		payload["stream"] = stream
	}
	_, hasMaxTokens := payload["max_tokens"]
	_, hasCompletionTokens := payload["max_completion_tokens"]
	if hasMaxTokens && hasCompletionTokens {
		writeError(w, http.StatusBadRequest, "max_tokens_conflict", "max_tokens와 max_completion_tokens 중 하나만 지정해 주세요.")
		return
	}
	for _, field := range []string{"max_tokens", "max_completion_tokens"} {
		if raw, ok := payload[field]; ok {
			value, valid := numberAsInt(raw)
			if !valid || value < 1 || value > item.MaxOutputTokens || value > 262144 {
				writeError(w, http.StatusBadRequest, "max_tokens_invalid", fmt.Sprintf("%s는 1~%d 사이여야 합니다.", field, item.MaxOutputTokens))
				return
			}
		}
	}
	if !hasMaxTokens && !hasCompletionTokens {
		payload["max_tokens"] = item.MaxOutputTokens
	}
	if !s.chatRequests.acquire(p.ID, item.ID) {
		w.Header().Set("Retry-After", "1")
		writeError(w, http.StatusTooManyRequests, "ai_concurrency_limited", "동시 AI 요청이 많습니다. 잠시 후 다시 시도해 주세요.")
		return
	}
	defer s.chatRequests.release(p.ID, item.ID)
	body, _ := json.Marshal(payload)
	ctx, cancel := context.WithTimeout(r.Context(), time.Duration(item.TimeoutSeconds)*time.Second)
	defer cancel()
	responseController := http.NewResponseController(w)
	_ = responseController.SetWriteDeadline(time.Now().Add(time.Duration(item.TimeoutSeconds+5) * time.Second))
	defer func() { _ = responseController.SetWriteDeadline(time.Time{}) }()
	upstream, _ := http.NewRequestWithContext(ctx, http.MethodPost, providerURL(item.BaseURL, "chat/completions"), bytes.NewReader(body))
	upstream.Header.Set("Content-Type", "application/json")
	upstream.Header.Set("Accept", "text/event-stream, application/json")
	if err := s.applyProviderAuth(upstream, item); err != nil {
		s.audit(r, p, "ai.chat", "ai_provider", item.ID.String(), "failure", map[string]any{"model": payload["model"], "reason": "provider_credentials_unavailable"})
		writeError(w, http.StatusServiceUnavailable, "provider_credentials_unavailable", "AI 공급자 인증 정보를 복호화하지 못했습니다. 암호화 키와 공급자 설정을 확인해 주세요.")
		return
	}
	client := *s.client
	client.Timeout = time.Duration(item.TimeoutSeconds) * time.Second
	started := time.Now()
	response, err := client.Do(upstream)
	if err != nil {
		s.audit(r, p, "ai.chat", "ai_provider", item.ID.String(), "failure", map[string]any{"model": payload["model"], "reason": "upstream_unreachable"})
		writeError(w, http.StatusBadGateway, "ai_upstream_unavailable", "AI 공급자에 연결하지 못했습니다.")
		return
	}
	defer response.Body.Close()
	if response.StatusCode < 200 || response.StatusCode >= 300 {
		upstreamBody, _ := io.ReadAll(io.LimitReader(response.Body, 64<<10))
		s.logger.Warn("AI upstream rejected request", "status", response.StatusCode, "provider_id", item.ID, "body_bytes", len(upstreamBody))
		s.audit(r, p, "ai.chat", "ai_provider", item.ID.String(), "failure", map[string]any{"model": payload["model"], "reason": "upstream_rejected", "status": response.StatusCode})
