func (s *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		principal, err := s.auth.Authenticate(r)
		if err != nil {
			s.writeAuthFailure(w, r, err, "로그인이 필요하거나 세션이 만료되었습니다.")
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), principalKey{}, principal)))
	})
}

// writeAuthFailure keeps a credential problem apart from a failure to check the
// credential at all. Reporting a database outage as 401 logs every operator out
// of a session that is still valid and tells API key callers their key was
// revoked, so an unverifiable credential answers 503 instead.
func (s *Server) writeAuthFailure(w http.ResponseWriter, r *http.Request, err error, message string) {
	if errors.Is(err, auth.ErrUnauthenticated) {
		writeError(w, http.StatusUnauthorized, "unauthenticated", message)
		return
	}
	s.logger.Warn("authentication backend failure", "error", err, "path", r.URL.Path)
	w.Header().Set("Retry-After", "1")
	writeError(w, http.StatusServiceUnavailable, "auth_unavailable", "인증 정보를 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.")
}

// mcpAuthenticate accepts the two credentials /mcp takes from one
// Authorization: Bearer header: a personal key (aia_…) exactly as before, or —
// only here, never on REST — a Keycloak access token when MCP SSO is on. A
// bearer that is neither gets the same "invalid key" answer it always got.
func (s *Server) mcpAuthenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !validOrigin(r) {
			writeError(w, http.StatusForbidden, "origin_denied", "허용되지 않은 Origin입니다.")
			return
		}
}

func principalFrom(ctx context.Context) auth.Principal {
	value, _ := ctx.Value(principalKey{}).(auth.Principal)
	return value
}

func (s *Server) require(permission string, handler http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		p := principalFrom(r.Context())
		if !p.HasPermission(permission) {
			s.audit(r, p, "permission.denied", permission, "", "denied", nil)
			writeError(w, http.StatusForbidden, "permission_denied", "이 작업을 수행할 권한이 없습니다.")
			return
		}
		if p.AuthMethod == "api_key" {
			scope := apiScopeForPermission(permission, r.Method)
			if scope != "" && !p.HasScope(scope) {
				writeError(w, http.StatusForbidden, "scope_denied", "API 키에 이 관리 API를 호출할 scope가 없습니다.", map[string]string{"requiredScope": scope})
				return
			}
		}
		handler(w, r)
	}
}

func (s *Server) requireAny(permissions []string, handler http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		p := principalFrom(r.Context())
		granted := ""
		for _, permission := range permissions {
			if p.HasPermission(permission) {
				granted = permission
				break
			}
		}
		if granted == "" {
			s.audit(r, p, "permission.denied", strings.Join(permissions, "|"), "", "denied", nil)
			writeError(w, http.StatusForbidden, "permission_denied", "이 작업을 수행할 권한이 없습니다.")
			return
		}
		if p.AuthMethod == "api_key" {
			scope := apiScopeForPermission(granted, r.Method)
			if scope != "" && !p.HasScope(scope) {
				writeError(w, http.StatusForbidden, "scope_denied", "API 키에 이 관리 API를 호출할 scope가 없습니다.", map[string]string{"requiredScope": scope})
				return
			}
		}
		handler(w, r)
	}
}

