func apiScopeForPermission(permission, method string) string {
	if permission == "ai.use" {
		return "ai:chat"
	}
	if permission == "keys.self" && (method == http.MethodGet || method == http.MethodHead) {
		return "profile:read"
	}
	if method == http.MethodGet || method == http.MethodHead {
		return "admin:read"
	}
	return "admin:write"
}

